import { RunService } from "@rbxts/services"
import type { Trove } from "@rbxts/trove"
import { Modding, observeElement } from "@typetorch/framework"
import { Tasks } from "./tasks"

/**
 * A `t` guard for `T`, generated by @typetorch/transformer (the instance guard Flamework generated for a component's
 * instance type: class plus required children).
 *
 * @metadata macro
 */
export function guardOf<T>(guard?: Modding.Generic<T, "guard">): (value: unknown) => value is T {
	return guard!
}

/**
 * World setup a component adds to an instance that outlives generations (a Root part, welds, a prompt, constraints on
 * a place model): built once and handed over to every later generation instead of rebuilt, like the template's
 * handoff.ts does for static world geometry (for the frames between two generations there is no code, and a rig torn
 * down there would drop the parts it holds). Returns true when it built the rig now, false when it was handed over.
 * `key` names and versions the setup; the instance's own lifetime ends it, as before.
 */
export function rigOnce(instance: Instance, key: string, build: () => void): boolean {
	const attribute = `TypeTorchRig_${key}`
	if (instance.GetAttribute(attribute) === true) return false
	build()
	instance.SetAttribute(attribute, true)
	return true
}

/**
 * The pose a moving part had before any generation animated it, so an animation a swap cut off restarts from home
 * instead of from wherever it stopped. Recorded once per instance (an attribute), like rigOnce.
 */
export function homePivot(instance: PVInstance, key: string): CFrame {
	const attribute = `TypeTorchHome_${key}`
	const saved = instance.GetAttribute(attribute)
	if (typeIs(saved, "CFrame")) return saved
	const pivot = instance.GetPivot()
	instance.SetAttribute(attribute, pivot)
	return pivot
}

/** Like homePivot, for any attribute value (a colour a generation changes and must be able to restore). */
export function homeValue<T extends AttributeValue>(instance: Instance, key: string, current: T): T {
	const attribute = `TypeTorchHome_${key}`
	const saved = instance.GetAttribute(attribute)
	if (saved !== undefined && typeOf(saved) === typeOf(current)) return saved as T
	instance.SetAttribute(attribute, current)
	return current
}

/**
 * One live tagged instance's behaviour (what a Flamework component was). A Components module builds it through
 * `observeElement`, so `trove` is cleaned when the instance loses the tag, leaves the world, stops passing its guard, or
 * the generation stops. Everything the component connects, spawns or creates goes in it.
 */
export abstract class TaggedComponent<I extends Instance = Instance> {
	constructor(
		readonly instance: I,
		protected readonly trove: Trove
	) {}

	/** Runs right after the constructor (Flamework's onStart). */
	onStart?(): void
	onTick?(dt: number): void
	onPhysics?(dt: number): void
	onRender?(dt: number): void
	/** Runs when the component's trove is cleaned, before the rest of it. */
	destroy?(): void
}

/** A component class; its guard (checked first) is what makes the instance the type its constructor takes. */
type ComponentClass<C extends TaggedComponent> = new (instance: never, trove: Trove) => C

const ATOMIC_MODES = new Set<Enum.ModelStreamingMode>([Enum.ModelStreamingMode.Atomic, Enum.ModelStreamingMode.Persistent])

/**
 * The live components of one generation, by class. Owned by a module (`ComponentsService` / `ComponentsController`),
 * which registers each tag in its trove and forwards its own onTick/onPhysics/onRender.
 */
export class ComponentRegistry {
	private readonly byClass = new Map<object, Map<Instance, TaggedComponent>>()
	/** Live components that have each per-frame hook (sorted once when built). */
	private readonly ticking = new Set<TaggedComponent>()
	private readonly physics_ = new Set<TaggedComponent>()
	private readonly rendering = new Set<TaggedComponent>()

	/**
	 * Builds `component` for every instance with `tag` that passes `guard`. As with Flamework's default (Contextual)
	 * streaming mode: on the client a non-atomic instance that fails the guard is watched until its descendants
	 * arrive (and loses the component if they go again); on the server the guard is checked once.
	 */
	register<C extends TaggedComponent>(
		trove: Trove,
		tag: string,
		component: ComponentClass<C>,
		guard: (value: unknown) => boolean
	) {
		const instances = new Map<Instance, TaggedComponent>()
		this.byClass.set(component, instances)
		observeElement<Instance>(trove, tag, (instance, elementTrove) => {
			let current: Trove | undefined
			const build = () => {
				const componentTrove = elementTrove.extend()
				current = componentTrove
				const built = new component(instance as never, componentTrove)
				instances.set(instance, built)
				if ("onTick" in built) this.ticking.add(built)
				if ("onPhysics" in built) this.physics_.add(built)
				if ("onRender" in built) this.rendering.add(built)
				componentTrove.add(() => {
					instances.delete(instance)
					this.ticking.delete(built)
					this.physics_.delete(built)
					this.rendering.delete(built)
					built.destroy?.()
				})
				built.onStart?.()
			}
			const qualify = () => {
				const passes = guard(instance)
				if (passes && !current) {
					build()
				} else if (!passes && current) {
					const built = current
					current = undefined
					elementTrove.remove(built)
				}
			}
			const atomic = instance.IsA("Model") && ATOMIC_MODES.has(instance.ModelStreamingMode)
			if (RunService.IsClient() && !atomic) {
				const tasks = new Tasks(elementTrove)
				let scheduled = false
				const recheck = () => {
					if (scheduled) return
					scheduled = true
					tasks.defer(() => {
						scheduled = false
						qualify()
					})
				}
				elementTrove.connect(instance.DescendantAdded, recheck)
				elementTrove.connect(instance.DescendantRemoving, recheck)
			}
			qualify()
		})
	}

	get<C extends TaggedComponent>(instance: Instance, component: abstract new (...args: never[]) => C): C | undefined {
		return this.byClass.get(component)?.get(instance) as C | undefined
	}

	all<C extends TaggedComponent>(component: abstract new (...args: never[]) => C): C[] {
		const found: C[] = []
		this.byClass.get(component)?.forEach((built) => found.push(built as C))
		return found
	}

	// One component that throws must not stop the others (a server cart's sanity sampling runs in onTick), so each
	// call is isolated and warned, like the framework's own listeners.
	tick(dt: number) {
		for (const built of this.ticking) this.step(built, "onTick", () => built.onTick!(dt))
	}

	physics(dt: number) {
		for (const built of this.physics_) this.step(built, "onPhysics", () => built.onPhysics!(dt))
	}

	render(dt: number) {
		for (const built of this.rendering) this.step(built, "onRender", () => built.onRender!(dt))
	}

	private step(built: TaggedComponent, name: string, run: () => void) {
		const [ok, err] = pcall(run)
		if (!ok) warn(`[components] ${built.instance.GetFullName()} ${name} threw: ${err}`)
	}
}
